const fs = require('node:fs'), vm = require('node:vm'), assert = require('node:assert/strict');
const html = fs.readFileSync('glp/servers/peoplesweb/web/index.html', 'utf8');
const funcs = html.slice(html.indexOf('const openBtn ='), html.indexOf('// The stages of the cascade'));
const expr = html.split('\n').find(s => s.includes('<p class="sum">${c.live') && s.includes('c.parametric')).trim();
const contracts = JSON.parse(fs.readFileSync('contracts.json', 'utf8'));
const ctx = vm.createContext({D:{contracts}, esc:s=>s, NM:id=>id.replaceAll('-', ' '), appUrl:()=>'/app'});
const render = vm.runInContext(funcs + '\n(c) => ({pill: openBtn(c), app: ' + '`' + expr + '`' + '})', ctx);
for (const c of contracts.filter(c=>c.parametric)) {
  const {pill, app} = render({...c,record:true,live:false});
  assert.match(pill, />Parametric</);
  assert.match(app,/a template with no app of its own/);
  assert.doesNotMatch(app,/No app yet/);
  if (c.id === 'Auction') assert.match(app, /<a data-go="Second-Score-Auction">Second Score Auction<\/a>/);
}
const refused = render({id:'Refusal',record:true,notCompiled:['control refusal']});
assert.match(refused.pill, />Not compiled</);
assert.match(refused.app,/No app yet\. The compiler refused it: control refusal/);
assert.match(render({id:'Live',live:true}).pill, />Open</);
console.log('Rendered three template cases, Auction instance link, refusal and live controls.');
